import{_ as t,a0 as o,w as d,s as c,I as a,x as n,a1 as l,A as i,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"使用 mlocate 查找文件 | LCTT x X-CMD","titleTemplate":false,"description":"使用 mlocate 查找文件 | LCTT (201711) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 mlocate 查找文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 mlocate 查找文件 | LCTT (201711) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201711/20171106 Finding Files with mlocate","title":"使用 mlocate 查找文件","tag":"201711","desc":""},"relativePath":"201711/20171106 Finding Files with mlocate.md","filePath":"[post].md"}'),r={name:"201711/20171106 Finding Files with mlocate.md"};function g(u,s,h,b,m,k){const e=o("Link");return d(),c("div",null,[s[24]||(s[24]=a("h1",{id:"使用-mlocate-查找文件",tabindex:"-1"},[n("使用 mlocate 查找文件 "),a("a",{class:"header-anchor",href:"#使用-mlocate-查找文件","aria-label":"Permalink to “使用 mlocate 查找文件”"},"​")],-1)),s[25]||(s[25]=a("p",null,[a("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/question-mark.jpg?itok=dIQlOWz7",alt:"mlocate",title:"mlocate"})],-1)),s[26]||(s[26]=a("p",null,[n("在这一系列的文章中，我们将来看下 "),a("code",null,"mlocate"),n("，来看看如何快速、轻松地满足你的需求。")],-1)),a("p",null,[l(e,{href:"https://www.linux.com/licenses/category/creative-commons-zero"},{default:i(()=>[...s[0]||(s[0]=[n("Creative Commons Zero",-1)])]),_:1}),s[1]||(s[1]=n("Pixabay",-1))]),s[27]||(s[27]=p(`<p>对于一个系统管理员来说，草中寻针一样的查找文件的事情并不少见。在一台拥挤的机器上，文件系统中可能存在数十万个文件。当你需要确定一个特定的配置文件是最新的，但是你不记得它在哪里时怎么办？</p><p>如果你使用过一些类 Unix 机器，那么你肯定用过 <code>find</code> 命令。毫无疑问，它是非常复杂和功能强大的。以下是一个只搜索目录中的符号链接，而忽略文件的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># find . -lname &quot;*&quot;</span></span></code></pre></div><p>你可以用 <code>find</code> 命令做几乎无尽的事情，这是不容否认的。<code>find</code> 命令好用的时候是很好且简洁的，但是它也可以很复杂。这不一定是因为 <code>find</code> 命令本身的原因，而是它与 <code>xargs</code> 结合，你可以传递各种选项来调整你的输出，并删除你找到的那些文件。</p><h3 id="位置、位置-让人沮丧" tabindex="-1">位置、位置，让人沮丧 <a class="header-anchor" href="#位置、位置-让人沮丧" aria-label="Permalink to “位置、位置，让人沮丧”">​</a></h3><p>然而，通常情况下简单是最好的选择，特别是当一个脾气暴躁的老板搭着你的肩膀，闲聊着时间的重要性时。你还在模糊地猜测这个你从来没有见过的文件的路径，而你的老板却肯定它在拥挤的 /var 分区的某处。</p><p>进一步看下 <code>mlocate</code>。你也许注意过它的一个近亲：<code>slocate</code>，它安全地（注意前缀字母 s 代表安全）记录了相关的文件权限，以防止非特权用户看到特权文件。此外，还有它们所起源的一个更老的，原始 <code>locate</code> 命令。</p><p><code>mlocate</code> 与其家族的其他成员（至少包括 <code>slocate</code>）的不同之处在于，在扫描文件系统时，<code>mlocate</code> 不需要持续重新扫描所有的文件系统。相反，它将其发现的文件（注意前面的 m 代表合并）与现有的文件列表合并在一起，使其可以借助系统缓存从而性能更高、更轻量级。</p><p>在本系列文章中，我们将更仔细地了解 <code>mlocate</code> （由于其流行，所以也简称其为 <code>locate</code>），并研究如何快速轻松地将其调整到你心中所想的方式。</p><h3 id="小巧和紧凑" tabindex="-1">小巧和 紧凑 <a class="header-anchor" href="#小巧和紧凑" aria-label="Permalink to “小巧和	紧凑”">​</a></h3><p>除非你经常重复使用复杂的命令，否则就会像我一样，最终会忘记它们而需要在用的时候寻找它们。<code>locate</code> 命令的优点是可以快速查询整个文件系统，而不用担心你处于顶层目录、根目录和所在路径，只需要简单地使用 <code>locate</code> 命令。</p><p>以前你可能已经发现 <code>find</code> 命令非常不听话，让你经常抓耳挠腮。你知道，丢失了一个分号或一个没有正确转义的特殊的字符就会这样。现在让我们离开这个复杂的 <code>find</code> 命令，放松一下，看一下这个聪明的小命令。</p><p>你可能需要首先通过运行以下命令来检查它是否在你的系统上：</p><p>对于 Red Hat 家族：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># yum install mlocate</span></span></code></pre></div><p>对于 Debian 家族：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt-get install mlocate</span></span></code></pre></div><p>发行版之间不应该有任何区别，但版本之间几乎肯定有细微差别。小心。</p><p>接下来，我们将介绍 <code>locate</code> 命令的一个关键组件，名为 <code>updatedb</code>。正如你可能猜到的那样，这是<strong>更新</strong> <code>locate</code> 命令的<strong>数据库</strong>的命令。这名字非常符合直觉。</p><p>这个数据库是我之前提到的 <code>locate</code> 命令的文件列表。该列表被保存在一个相对简单而高效的数据库中。<code>updatedb</code> 通过 cron 任务定期运行，通常在一天中的安静时间运行。在下面的清单 1 中，我们可以看到文件 <code>/etc/cron.daily/mlocate.cron</code> 的内部（该文件的路径及其内容可能因发行版不同）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>nodevs=$(&lt; /proc/filesystems awk &#39;$1 == &quot;nodev&quot; { print $2 }&#39;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>renice +19 -p $$ &gt;/dev/null 2&gt;&amp;1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ionice -c2 -n7 -p $$ &gt;/dev/null 2&gt;&amp;1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/usr/bin/updatedb -f &quot;$nodevs&quot;</span></span></code></pre></div><p><strong>清单 1：</strong> 每天如何触发 “updatedb” 命令。</p><p>如你所见，<code>mlocate.cron</code> 脚本使用了优秀的 <code>nice</code> 命令来尽可能少地影响系统性能。我还没有明确指出这个命令每天都在设定的时间运行（但如果我没有记错的话，原始的 <code>locate</code> 命令与你在午夜时的计算机减速有关）。这是因为，在一些 “cron” 版本上，延迟现在被引入到隔夜开始时间。</p><p>这可能是因为所谓的 “<ruby>河马之惊群<rt>Thundering Herd of Hippos</rt></ruby>”问题。想象许多计算机（或饥饿的动物）同时醒来从单一或有限的来源要求资源（或食物）。当所有的“河马”都使用 NTP 设置它们的手表时，这可能会发生（好吧，这个寓言扯多了，但请忍受一下）。想象一下，正好每五分钟（就像一个 “cron 任务”），它们都要求获得食物或其他东西。</p><p>如果你不相信我，请看下配置文件 - 清单 2 中名为 <code>anacron</code> 的 cron 版本，这是文件 <code>/etc/anacrontab</code> 的内容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># /etc/anacrontab: configuration file for anacron</span></span>
<span class="line"><span></span></span>
<span class="line"><span># See anacron(8) and anacrontab(5) for details.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SHELL=/bin/sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PATH=/sbin:/bin:/usr/sbin:/usr/bin</span></span>
<span class="line"><span></span></span>
<span class="line"><span>MAILTO=root</span></span>
<span class="line"><span></span></span>
<span class="line"><span># the maximal random delay added to the base delay of the jobs</span></span>
<span class="line"><span></span></span>
<span class="line"><span>RANDOM_DELAY=45</span></span>
<span class="line"><span></span></span>
<span class="line"><span># the jobs will be started during the following hours only</span></span>
<span class="line"><span></span></span>
<span class="line"><span>START_HOURS_RANGE=3-22</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#period in days   delay in minutes   job-identifier   command</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1       5       cron.daily              nice run-parts /etc/cron.daily</span></span>
<span class="line"><span></span></span>
<span class="line"><span>7       25      cron.weekly             nice run-parts /etc/cron.weekly</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@monthly 45     cron.monthly            nice run-parts /etc/cron.monthly</span></span></code></pre></div><p><strong>清单 2：</strong> 运行 “cron” 任务时延迟是怎样被带入的。</p><p>从清单 2 可以看到 <code>RANDOM_DELAY</code> 和 “delay in minutes” 列。如果你不熟悉 cron 这个方面，那么你可以在这找到更多的东西：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># man anacrontab</span></span></code></pre></div>`,29)),a("p",null,[s[3]||(s[3]=n("否则，如果你愿意，你可以自己延迟一下。有个",-1)),l(e,{href:"http://www.moundalexis.com/archives/000076.php"},{default:i(()=>[...s[2]||(s[2]=[n("很棒的网页",-1)])]),_:1}),s[4]||(s[4]=n("（现在已有十多年的历史）以非常合理的方式讨论了这个问题。本网站讨论如何使用 ",-1)),s[5]||(s[5]=a("code",null,"sleep",-1)),s[6]||(s[6]=n(" 来引入一个随机性，如清单 3 所示。",-1))]),s[28]||(s[28]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Grab a random value between 0-240.</span></span>
<span class="line"><span>value=$RANDOM</span></span>
<span class="line"><span>while [ $value -gt 240 ] ; do</span></span>
<span class="line"><span> value=$RANDOM</span></span>
<span class="line"><span>done</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Sleep for that time.</span></span>
<span class="line"><span>sleep $value</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Syncronize.</span></span>
<span class="line"><span>/usr/bin/rsync -aqzC --delete --delete-after masterhost::master /some/dir/</span></span></code></pre></div>`,1)),a("p",null,[s[8]||(s[8]=a("strong",null,"清单 3：",-1)),s[9]||(s[9]=n("在触发事件之前引入随机延迟的 shell 脚本，以避免",-1)),l(e,{href:"http://www.moundalexis.com/archives/000076.php"},{default:i(()=>[...s[7]||(s[7]=[n("河马之惊群",-1)])]),_:1}),s[10]||(s[10]=n("。",-1))]),s[29]||(s[29]=p(`<p>在提到这些（可能令人惊讶的）延迟时，是指 <code>/etc/crontab</code> 或 root 用户自己的 crontab 文件。如果你想改变 <code>locate</code> 命令运行的时间，特别是由于磁盘访问速度减慢时，那么它不是太棘手。实现它可能会有更优雅的方式，但是你也可以把文件 <code>/etc/cron.daily/mlocate.cron</code> 移到别的地方（我使用 <code>/usr/local/etc</code> 目录），使用 root 用户添加一条记录到 root 用户的 crontab，粘贴以下内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># crontab -e</span></span>
<span class="line"><span></span></span>
<span class="line"><span>33 3 * * * /usr/local/etc/mlocate.cron</span></span></code></pre></div><p>使用 anacron，而不是通过 <code>/var/log/cron</code> 以及它的旧的、轮转的版本，你可以快速地告诉它上次 cron.daily 任务被触发的时间：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ls -hal /var/spool/anacron</span></span></code></pre></div><p>下一次，我们会看更多的使用 <code>locate</code>、<code>updatedb</code> 和其他工具来查找文件的方法。</p><hr>`,6)),a("p",null,[s[12]||(s[12]=n("via: ",-1)),l(e,{href:"https://www.linux.com/blog/learn/intro-to-linux/2017/11/finding-files-mlocate"},{default:i(()=>[...s[11]||(s[11]=[n("https://www.linux.com/blog/learn/intro-to-linux/2017/11/finding-files-mlocate",-1)])]),_:1})]),a("p",null,[s[16]||(s[16]=n("作者：",-1)),l(e,{href:"https://www.linux.com/users/chrisbinnie"},{default:i(()=>[...s[13]||(s[13]=[n("CHRIS BINNIE",-1)])]),_:1}),s[17]||(s[17]=n(" 译者：",-1)),l(e,{href:"https://github.com/geekpi"},{default:i(()=>[...s[14]||(s[14]=[n("geekpi",-1)])]),_:1}),s[18]||(s[18]=n(" 校对：",-1)),l(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[15]||(s[15]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[21]||(s[21]=n("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[19]||(s[19]=[n("LCTT",-1)])]),_:1}),s[22]||(s[22]=n(" 原创编译，",-1)),l(e,{href:"https://linux.cn/"},{default:i(()=>[...s[20]||(s[20]=[n("Linux中国",-1)])]),_:1}),s[23]||(s[23]=n(" 荣誉推出",-1))])])}const T=t(r,[["render",g]]);export{C as __pageData,T as default};
